{"HelperA.dfy": "if i == 0 {
  O1.Unfold(s, j);
  O2.Expose(s, j);
  O1.Unfold(s, 0);
  O2.Expose(s, 0);
  assert K.Prefix(s, 0) == 0;
  assert K.Prefix(s, 0 + j) == K.Prefix(s, 0) + K.Prefix(s[0..], j);
} else {
  O1.Unfold(s, i + j);
  O2.Expose(s, i + j);
  O1.Unfold(s, i);
  O2.Expose(s, i);
  Prove(s[1..], i - 1, j);
  assert s[1..][i-1..] == s[i..];
}"}

